INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5baa3924-1bee-4ee9-91df-64ba25bd7f8d', '21feff02-016d-46e2-bb9d-c27495133b1b', '101. óra: Feladatmegoldás', 'Összetett kerületszámítási és kerítésszámítási szöveges feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "8f5b3cf9-bb55-4979-85bf-1568771f2b19", "text": "Egy téglalap alakú kert hossza 20 m, szélessége 15 m. Hány méter kerítés övezi a kertet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "7b9402cf-5464-47e7-b3b4-bf95f6ada968", "text": "Hány méter kerítés kell a 20m x 15m-es kerthez, ha hagyunk egy 2 m-es kaput? (70 - 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "68"}, {"id": "857be294-8dc5-4723-89ab-e38331e13394", "text": "Egy négyzet alakú pálya kerülete 100 m. Hány méter hosszú a pálya egy oldala? (100 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "5160fe0d-9925-45d6-ab7b-e9374d8ac36d", "text": "Ha a téglalap kerülete 30 cm, és egyik oldala 5 cm, mekkora a másik oldal? (15 - 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "7873c659-b971-41eb-ad46-6bc602ba9ee2", "text": "A sokszögek kerületét mindig hosszúság-mértékegységben (m, cm, mm) adjuk meg.", "type": "true-false", "options": [{"id": "bfa6a61f-7647-4655-b3f0-b58c5ef67045", "text": "Igaz", "isCorrect": true}, {"id": "68fe04ed-6ab9-4d9e-a208-10ff1799ba78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c7d30ee-8d70-48c5-9a66-0a289f3b5be8", "text": "Mennyi a 10 cm oldalú szabályos hatszög kerülete?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "59d362ec-2b96-4de7-9e9f-d91799881085", "text": "A kerületszámításos feladatoknál az oldalaknak azonos mértékegységben kell lenniük.", "type": "true-false", "options": [{"id": "43c624bf-569b-4117-b4e7-cf795cdf23b2", "text": "Igaz", "isCorrect": true}, {"id": "4f0c3e03-ba4a-4612-be30-88d183f5439c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('85c72b4d-e664-48ef-a082-8d74f7263403', '21feff02-016d-46e2-bb9d-c27495133b1b', '102. óra: A terület és a térfogat mérése', 'A terület és térfogat mértékegységei, lefedés, egységkockák, átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "feaab643-21d4-4262-936e-b763e7b707fc", "text": "Mi a terület alapvető mértékegysége az SI-ben?", "type": "multiple-choice", "options": [{"id": "ad79f7d3-a176-433a-8e60-1ad5f8c2b5fa", "text": "Négyzetméter (m²)", "isCorrect": true}, {"id": "be34fce8-4fb5-4f00-8696-4ac8d9a2e74f", "text": "Méter (m)", "isCorrect": false}, {"id": "96fcd62d-98a0-4b3a-8260-e214c79ddaf5", "text": "Köbméter (m³)", "isCorrect": false}, {"id": "388bd09d-7685-4d37-b6b7-6c5d363b788b", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "db2646da-ccce-4f2f-bc1e-96cb28457d30", "text": "Hány cm² 1 dm²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "bc50ffe4-0683-43e3-a433-eafd148a0b07", "text": "Hány dm² 1 m²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "46aed42c-0f18-41d5-89a0-9b384357883d", "text": "Hány dm³ 1 m³? (10 * 10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "9c8e5e06-283c-4e89-bf20-681a49fbdd3d", "text": "1 liter űrtartalom pontosan 1 köbdeciméternek (1 dm³) felel meg.", "type": "true-false", "options": [{"id": "e3f63004-2669-45a5-b725-d8488e0c50ce", "text": "Igaz", "isCorrect": true}, {"id": "07d86c13-dfca-4b5a-82ad-886052f6fa2f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7219267f-62f9-46f2-8289-fae7bbe32386", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "3f105551-969f-4891-ae5c-a96438273051", "text": "A terület mértékegységei között a szomszédos váltószám 100 (területnél 10²).", "type": "true-false", "options": [{"id": "879fa54d-93a9-41b4-910a-e173e5d763b5", "text": "Igaz", "isCorrect": true}, {"id": "1f3c4aba-352a-4193-8126-ca400cff19bd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('70ecea26-ec5b-4124-aff5-9196a26d280d', '21feff02-016d-46e2-bb9d-c27495133b1b', '103. óra: Gyakorlóóra. A terület és a térfogat mérése', 'Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "d75a0858-5750-4cea-a56a-ad5457d80e34", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "4b86dd05-2aa4-438e-b52c-e14bc383a4f6", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "e1167037-df58-4f33-bdf5-01427409af39", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "7e27deb5-6d46-4b0c-b533-595d919418b7", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "8d8599ad-45e7-4b8a-bae9-a9c04e149eb4", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "161fe7cc-4bc5-49c1-9db6-a3f562ee0656", "text": "Igaz", "isCorrect": true}, {"id": "83946d97-bcae-41ea-b069-85451fc6a6ef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "48ffe304-0771-41e5-a9d5-fe22550bd9b1", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "bdc315cc-2a04-41ca-b171-0cf23a419d56", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f7aab06f-ea32-4c29-a20f-8d7ce90ac537', '21feff02-016d-46e2-bb9d-c27495133b1b', '104. óra: A sokszögek területe', 'Négyzet, téglalap és derékszögű háromszög területe (T).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "4abe35fd-62a9-4bd0-8fa3-922fba07419a", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "08b97268-16b9-4fa0-8cfe-3bd2588af61b", "text": "T = a * b", "isCorrect": true}, {"id": "90c14e35-5145-4e7c-96dc-edca7ef51c9e", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "e0dc5029-5c8d-4ab6-83fa-62bf660a262f", "text": "T = a + b", "isCorrect": false}, {"id": "6b5a3129-9fd1-4df8-84a0-f05ce10300fa", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "50b326f8-61be-40ad-aa06-32a63461c9df", "text": "Mi a négyzet területének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "fc02dab8-ba21-486b-91d4-1b6882b9ab0b", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "b9ea43e4-f081-4b9b-802c-4ec3a4256986", "text": "T = 4 * a", "isCorrect": false}, {"id": "4234a1cf-88b8-4582-9759-683a0067015d", "text": "T = 2 * a", "isCorrect": false}, {"id": "2003dff7-aaa2-4f0a-89c9-c90203673aef", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "36fbdf9f-e9bd-4e85-9682-8f76937af402", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "0253ffaf-13f5-4e04-8274-1658e893c587", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "fdf5cbd2-b2b4-4414-9883-27abc09ccaa6", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "ce39cf08-cd0c-4c7c-9752-f9ea81f4c5a3", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "987463da-6853-4060-af8f-77537e6cbd0d", "text": "T = a * b", "isCorrect": false}, {"id": "cd9da275-a023-4b4f-a723-22019eb897e0", "text": "T = a + b", "isCorrect": false}, {"id": "eb546d2f-4870-478e-a4d7-d70b94cda964", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "f65dcba1-1e83-45cb-b30b-536bd6b79053", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "6fd38e7c-ff63-4d76-9bf3-df9340ec8ece", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "7c80d7d4-8312-4d6f-b5f2-fba9109e6cf0", "text": "Igaz", "isCorrect": true}, {"id": "d11d1d70-3ede-4f51-a0c5-e9571e3c798d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4e69ccbf-ecd6-41c0-826e-bf52806b43d1', '21feff02-016d-46e2-bb9d-c27495133b1b', '105. óra: Feladatmegoldás', 'Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "94cc62b7-addc-4910-b865-7b895fadfc48", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "8429f7d8-3776-40b4-936b-b36e52f535be", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "da4c17e7-87ae-4a52-9ab1-46f4cba5c594", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "f33a991f-6b35-4a5d-898e-427662ff7d7c", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "cc377eee-5d2c-47fa-8afd-d7de9ad0c0f2", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "483e8232-d5fd-4ba3-b2ee-9dffedff4e1f", "text": "Igaz", "isCorrect": true}, {"id": "6895983e-7ec7-43db-baf6-912d75166fa9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "55671fc6-eb2a-412f-915d-68b9c371c642", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "fcbbfcf4-c2db-412c-9003-d24397655d06", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "874274e8-0624-4114-88d6-093f865b4546", "text": "Igaz", "isCorrect": true}, {"id": "c9f3ecb7-6e2c-4a58-83ea-d9dd9a7fb628", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4fdeb981-9c61-4b28-9643-fa351a4ef62c', '21feff02-016d-46e2-bb9d-c27495133b1b', '106. óra: Alakzatok a térben', 'Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "329a42ad-abc2-4374-bb34-8c802e0ffe60", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "8e97b9de-14ee-45e6-ba33-e0d994befd8c", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "83c6928a-a2b5-484a-8f8a-fb812347b601", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "82b84fdb-0dc2-4fb3-9d84-d533a2944d7a", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "8c94b136-347c-4f7a-9e52-6f76f259a292", "text": "Igaz", "isCorrect": true}, {"id": "e708b4c9-c54c-4d89-8b5f-9a2dba2649ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6ac5cb60-1492-4821-8fc4-7175133b6e43", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "83cf4a65-ba93-46ab-b937-8c7ff2b83b82", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "062b516f-6146-43d0-8bc0-e2206ea5915e", "text": "Háromszögek", "isCorrect": false}, {"id": "5565b5fd-2c81-4e1b-87f8-b4dabbcd778d", "text": "Körök", "isCorrect": false}, {"id": "400cfd2f-5acd-4c1e-8ca9-fdd9ddd123e1", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "cc422812-6c15-45cb-90b8-b7656cf12c62", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "2f24e667-241b-4545-a087-5595cf934d80", "text": "Igaz", "isCorrect": true}, {"id": "cc6aa83f-4b2a-4eb4-b3bd-9403bc3207cd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "be76e2cc-8fb0-4e9f-8985-822fd7bef342", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('352ed95b-446a-4906-aac6-2066c2e5c568', '21feff02-016d-46e2-bb9d-c27495133b1b', '107. óra: Testek felszíne', 'Kocka és téglatest felszínének kiszámítása (A vagy F).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "0c038818-f768-41f9-b49d-55a1a563cd00", "text": "Mi a kocka felszínének képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "205b3e3f-cbcb-41fd-a8ec-73a8ea3e3e86", "text": "F = 6 * a * a (6 * a²)", "isCorrect": true}, {"id": "9268c88f-4718-401a-bb5e-88d0677dec46", "text": "F = a * a * a", "isCorrect": false}, {"id": "bb2fd594-d3f4-4f57-b01d-117140c86fd3", "text": "F = 12 * a", "isCorrect": false}, {"id": "f96e7bed-e3b8-4bf9-a06c-5327fc9a1f02", "text": "F = 4 * a²", "isCorrect": false}], "timeLimit": 15}, {"id": "d0bb5f25-c83f-4c92-b40f-19a5321de611", "text": "Mi a téglatest felszínének képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "9de05a6e-1a08-4448-8def-de62cd63e132", "text": "F = 2 * (a*b + a*c + b*c)", "isCorrect": true}, {"id": "9fa57ed7-fa4e-421e-8270-7416aca12450", "text": "F = a * b * c", "isCorrect": false}, {"id": "d64be51f-9608-4456-b3a5-5390d4e47bbc", "text": "F = 4 * (a + b + c)", "isCorrect": false}, {"id": "b424413a-0020-44f8-a8ee-4a680573f6c4", "text": "F = a*b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "9010d898-d29a-4769-bc70-56b504d631f0", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "e4cd4711-9673-4f87-8085-a8e3de036647", "text": "Mennyi a 2 cm, 3 cm, 4 cm élű téglatest felszíne? (2*(2*3 + 2*4 + 3*4) = 2*(6+8+12) = 2*26)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "52"}, {"id": "e8fbaeb9-65af-40bd-93f5-05ce8d9dc706", "text": "A felszín a testet határoló lapok területeinek összege.", "type": "true-false", "options": [{"id": "b3b84d87-eb94-466e-89bd-5b69eaac33b5", "text": "Igaz", "isCorrect": true}, {"id": "0382ec3c-7523-4bdc-b972-642a09024990", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f1228b90-c90b-473e-aad4-7e285389e3a8", "text": "A felszínt mindig terület-mértékegységben (cm², m²) adjuk meg.", "type": "true-false", "options": [{"id": "3961e53c-3f58-4d24-adec-80b73a90131f", "text": "Igaz", "isCorrect": true}, {"id": "44fd394b-5e96-46f4-9fd5-2249496e1d2f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5117ac0d-b0b5-4700-9ec7-2792d0e607e5", "text": "Mennyi a 10 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a60f9a0f-0194-4bb0-bd47-385ed5b64ed4', '21feff02-016d-46e2-bb9d-c27495133b1b', '108. óra: Gyakorlóóra', 'Felszínszámítás gyakorlása hálók megrajzolásával és szerkesztőprogrammal.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "2cbd9c35-7446-4110-a8ae-4218e3ae458f", "text": "Hány négyzetből áll a kocka hálója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "5cf48381-4c66-423b-984e-c39b716f3781", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "09c046b6-f0d1-4dbf-ad78-7665d6249935", "text": "Mennyi a 1 m, 2 m, 3 m élű téglatest felszíne? (2*(2+3+6) = 2*11)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "13913827-bf24-4116-a856-8b9b7d690b61", "text": "A test hálójának területe megegyezik a test felszínével.", "type": "true-false", "options": [{"id": "7759064e-2695-4ed1-82ce-f0448c9f355d", "text": "Igaz", "isCorrect": true}, {"id": "a1b01185-754c-4344-8efd-8a5851309299", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "05dcd534-664e-444c-849f-90c0b356274f", "text": "Mennyi a 5 cm élű kocka felszíne? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "3354ae76-0260-4d23-a918-9e4783e94ff1", "text": "Dinamikus szerkesztőprogrammal a testek hálója kiteríthető és összehajtható.", "type": "true-false", "options": [{"id": "06216b7a-c168-47e6-854d-cd91d85dbad3", "text": "Igaz", "isCorrect": true}, {"id": "c0a0e837-df32-40dd-b707-0c4eca32c042", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "915b6d6c-46d6-44a1-8d30-2127fbfb07b5", "text": "A téglatest szemközti lapjai egyenlő területűek.", "type": "true-false", "options": [{"id": "24f4cc47-a741-4b4a-8be8-6cc51b7c6343", "text": "Igaz", "isCorrect": true}, {"id": "63f9c2a3-29ac-4f89-86a0-49a347e92d5d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1602b35b-16a5-4cc3-a8f6-67eb258a3166', '21feff02-016d-46e2-bb9d-c27495133b1b', '109. óra: Felszínszámítással kapcsolatos gyakorlati feladatok', 'Dobozok lefestése, csomagolópapír szükséglet kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "c43a19b7-164f-4139-bcbd-b63bdadffd9e", "text": "Egy 10 cm x 20 cm x 30 cm-es téglatest dobozt befestünk. Hány cm² felületet kell lefesteni? (2*(200+300+600) = 2*1100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2200"}, {"id": "e5067f76-6614-478a-8462-678eeb1a07c7", "text": "Hány cm² csomagolópapír kell egy 5 cm élű kocka alakú ajándék becsomagolásához (ráhagyás nélkül)? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "622e7ac3-d4c2-47a0-991e-779ed5e07b0e", "text": "Ha a festékből 1 m²-re 200 g kell, hány gramm festék kell 5 m² felszínre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "9b46eb0a-1001-4f8a-a62d-f40a58ece3b0", "text": "Csomagoláskor a veszteség és az átfedés miatt érdemes a kiszámított felszínnél kb. 10-20%-kal több papírral számolni.", "type": "true-false", "options": [{"id": "cc47ed07-f279-41da-8951-7cfb83ca969d", "text": "Igaz", "isCorrect": true}, {"id": "22c4419c-1bed-43f9-98e9-f430150daabb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c559c74f-589a-4aea-9cf1-0e3020bcfaaf", "text": "Mennyi a 2 cm élű kocka felszíne? (6 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "517be3e1-4998-46ce-b91e-81e8611e3793", "text": "A dobozok tervezésénél az anyagszükségletet a felszín határozza meg.", "type": "true-false", "options": [{"id": "9b731b75-a6a4-4fe5-b7a8-97a1e0d46e33", "text": "Igaz", "isCorrect": true}, {"id": "670f7b08-ce66-48d2-8a4f-17c91642f1b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "459d1b8a-ffa3-4849-a291-cbacd57f0f97", "text": "Mennyi a 1 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('762121b8-5752-44fc-a1c3-19021dae98c4', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "b8ce8283-5b71-4cca-90bb-7fc760c38b20", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "d1af5675-48b1-4c61-8186-714ad67b2d4b", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "d310229e-b902-4c95-bc87-8da2c3a66a56", "text": "V = 6 * a²", "isCorrect": false}, {"id": "c2fb2fe0-89eb-4b74-bc7f-c5db16b9f8aa", "text": "V = 12 * a", "isCorrect": false}, {"id": "5e3f9411-865f-48ed-9ede-58501808f53b", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "ba15ebe8-3839-41ce-8f96-822eb85c1c83", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "f8bf3d7f-fc38-42b2-8b9b-adf44e04791b", "text": "V = a * b * c", "isCorrect": true}, {"id": "87424fab-048a-4f95-9db4-bb9c290f80e0", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "a15c10d1-3144-48a2-8007-739032e247b9", "text": "V = a * b", "isCorrect": false}, {"id": "f56f964b-148b-4555-9a94-1e86ee8fdb09", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "fbed3802-663c-44b7-9cd4-f643005706d8", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "cd095eff-ffb7-48de-a803-13beccd3795e", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "7224dd7c-082d-4a73-b103-794c6776c978", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "a37fadbd-5296-4e1a-a507-b744adecd3d8", "text": "Igaz", "isCorrect": true}, {"id": "93fd8c3a-beaa-405f-beb2-7694baa254b9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d39634bc-1384-4e9a-b57e-924b4a30eadc", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "48219946-7de7-4816-977e-7270f7dcf76d", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;